/* Prestige Wellness: a dependency-free, client-side concept.
   This is NOT an appointment, payment, medical, or authentication backend.
   Dates and hours use Asia/Manila. All operational data is synthetic. */
(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = value => value == null ? 'To be confirmed' : '\u20b1' + Math.round(Number(value) || 0).toLocaleString('en-PH');
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const STORE_KEY = 'prestige-concept-v1';
  const TZ = 'Asia/Manila';
  const STAFF = ['Specialist A', 'Specialist B', 'Specialist C'];
  const ROOMS = ['Suite 1', 'Suite 2', 'Together suite'];
  const BUFFER = 15;
  const dateParts = new Intl.DateTimeFormat('en-CA', {timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'});
  function today() { const p = Object.fromEntries(dateParts.formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`; }
  function offsetDate(day, n) { const d = new Date(day + 'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10); }
  function minuteNow() { const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:TZ,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return Number(p.hour)*60+Number(p.minute); }
  function prettyDate(day, opts={weekday:'short',month:'short',day:'numeric'}) {return new Intl.DateTimeFormat('en-PH',{timeZone:TZ,...opts}).format(new Date(day+'T12:00:00+08:00'));}
  function timeLabel(min) {return `${Math.floor(min/60)%12 || 12}:${String(min%60).padStart(2,'0')} ${min>=720?'PM':'AM'}`;}
  const validDate = day => /^\d{4}-\d{2}-\d{2}$/.test(day) && !Number.isNaN(Date.parse(day+'T12:00:00+08:00'));
  const inBookingRange = day => validDate(day) && day>=today() && day<=offsetDate(today(),60);
  const v = (minutes, price) => ({minutes,price});
  const SERVICES = [
    {id:'signature',name:'Prestige Signature Massage',short:'Prestige Signature',category:'restore',description:'A blend of Thai, Shiatsu, and Swedish techniques. Make the moment your own.',variants:[v(60,1800),v(90,2100),v(120,2699)],couples:true,source:'Primer, Jan 6, 2026'},
    {id:'lymphatic',name:'Lymphatic Massage',short:'Lymphatic Massage',category:'restore',description:'A gentle massage option for your next quiet moment. Discuss suitability with the spa.',variants:[v(90,2100),v(120,2700)],couples:true,source:'Primer, Jan 6, 2026'},
    {id:'combination',name:'Signature + Lymphatic',short:'Signature + Lymphatic',category:'restore',description:'A combined 90-minute massage ritual.',variants:[v(90,2600)],couples:true,source:'Primer, Jan 6, 2026'},
    {id:'scrub',name:'Full Body Scrub',short:'Full Body Scrub',category:'restore',description:'An unhurried body-care ritual. Ask the team about options and current prices.',variants:[v(45,null)],enquiry:true,source:'Supplied VIP artwork, Jun 29, 2025'},
    {id:'hydrafacial',name:'HydraFacial / Skin Enquiry',short:'HydraFacial',category:'renew',description:'Explore facial options with the team. Current treatment details, duration, and pricing need confirmation.',variants:[],enquiry:true,source:'Supplied artwork and Primer'},
    {id:'consultation',name:'Aesthetics Consultation',short:'Aesthetics Consultation',category:'refine',description:'A conversation about your aesthetic interests, not a booking for a medical procedure. Suitability, practitioner credentials, treatment details, and fees require confirmation.',variants:[v(30,null)],demoDuration:true,source:'Consultation-first concept; services referenced in supplied artwork'},
    {id:'wax-underarm',name:'Underarm Waxing',short:'Underarm Waxing',category:'smooth',description:'An individual waxing appointment. Duration here is an illustrative scheduling setting.',variants:[v(20,399)],demoDuration:true,source:'Supplied waxing artwork, Oct 27, 2024'},
    {id:'wax-legs',name:'Full Legs Waxing',short:'Full Legs Waxing',category:'smooth',description:'A beauty-care ritual. Duration here is an illustrative scheduling setting.',variants:[v(45,999)],demoDuration:true,source:'Supplied waxing artwork, Oct 27, 2024'},
    {id:'wax-brazilian',name:'Brazilian Waxing',short:'Brazilian Waxing',category:'smooth',description:'An individual waxing enquiry and appointment preview. Duration is illustrative.',variants:[v(30,1199)],demoDuration:true,source:'Supplied waxing artwork, Oct 27, 2024'}
  ];
  const WAX_MENU = [['Full Arms',799],['Half Arms',499],['Under Arm',399],['Full Back',799],['Full Legs',999],['Half Legs',499],['Brazilian',1199],['Boyzilian',1999],['Full Face',599],['Eyebrows',299],['Upper Lip',249],['Lower Lip',299]];
  const PACKAGES = {
    reset:{id:'reset',name:'The Prestige Reset',price:34000,total:12,used:3,extra:0,extraUsed:0,description:'12 massages of your choice, 120 minutes each.',label:'Reset preview guest'},
    glow:{id:'glow',name:'The Prestige Glow',price:51500,total:12,used:4,extra:6,extraUsed:2,extraName:'body scrubs',description:'12 massages of your choice, 120 minutes each, plus 6 full body scrubs of 45 minutes.',label:'Glow preview guest'},
    body:{id:'body',name:'Body by Prestige',price:25000,total:6,used:1,extra:6,extraUsed:1,extraName:'wood-sculpting treatments',description:'6 massages of your choice, 120 minutes each, plus 6 wood-sculpting treatments.',label:'Body preview guest'}
  };
  const CATEGORIES = {
    restore:{description:'Massage and bodywork. Choose a little time to step away from the everyday.',image:'assets/skin-detail.webp',label:'THE RESTORE EDIT'},
    renew:{description:'Skin care begins with understanding your skin. Explore available facial treatments with the team.',image:'assets/portrait-close.webp',label:'THE RENEW EDIT'},
    refine:{description:'Explore advanced aesthetics through a consultation first. This preview does not offer direct procedure bookings.',image:'assets/portrait.webp',label:'THE REFINE EDIT'},
    smooth:{description:'Thoughtful finishing touches, at your own pace. Prices below are historical references.',image:'assets/skin-detail.webp',label:'THE SMOOTH EDIT'}
  };
  const serviceById = id => SERVICES.find(s=>s.id===id);
  let store, toastTimer, activeRitual='restore', book=null, studioTab='overview', reportPeriod=7;
  let appFilter='upcoming', appQuery='', pendingReschedule=null, isAnimatingClose=false;

  function seedStore() {
    const base=today(); const appointments=[];
    const demoServices=['signature','lymphatic','signature','combination','wax-underarm','signature'];
    for(let day=-29;day<=6;day++) {
      const date=offsetDate(base,day);
      const count=day<0 ? 4+((day+30)%4) : day===0 ? 5 : 2+(day%3);
      for(let i=0;i<count;i++) {
        const s=serviceById(demoServices[(i+day+30)%demoServices.length]);
        const variant=s.variants[(i+day+30)%s.variants.length];
        const start=600+i*90;
        const cancelled=day<0 && (i+day+30)%11===0;
        const status=cancelled?'cancelled':day<0?'completed':'booked';
        appointments.push({id:`DEMO-${date.replace(/-/g,'')}-${i+1}`,date,start,serviceId:s.id,minutes:variant.minutes,price:variant.price,guests:1,therapists:[STAFF[i%3]],room:ROOMS[i%3],status,guest:`Sample guest ${String((i+day+30)%18+1).padStart(2,'0')}`,guestType:(i+day+30)%3===0?'new':'returning',source:['Google (demo)','Instagram (demo)','Direct (demo)'][(i+day+30)%3],packageId:null,createdBy:'seed'});
      }
    }
    return {schema:1,seedDate:base,appointments,disabledServices:[]};
  }
  function loadStore() {
    try {
      const data=JSON.parse(localStorage.getItem(STORE_KEY)||'null');
      if(data && data.schema===1 && data.seedDate===today() && Array.isArray(data.appointments) && Array.isArray(data.disabledServices)) {
        data.appointments=data.appointments.filter(a=>a && serviceById(a.serviceId) && validDate(a.date) && Number.isFinite(a.start) && Number.isFinite(a.minutes) && Array.isArray(a.therapists) && ['booked','completed','cancelled'].includes(a.status));
        return data;
      }
    } catch(error) { /* Local files or private mode may block storage. In-memory works. */ }
    return seedStore();
  }
  function saveStore(){ try{localStorage.setItem(STORE_KEY,JSON.stringify(store));}catch(error){/* Keep in-memory demonstration functional. */} }
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
  function animateContent(el) {if(!reducedMotion.matches && el && el.animate)el.animate([{opacity:0,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'cubic-bezier(.22,1,.36,1)'});}
  function showDialog(id){const el=$('#'+id);el.classList.remove('is-closing');if(!el.open)el.showModal();document.body.classList.add('modal-open');}
  function closeDialog(id, after){const el=$('#'+id);if(!el || !el.open){after?.();return;}if(el.classList.contains('is-closing'))return;el.classList.add('is-closing');const finish=()=>{el.close();el.classList.remove('is-closing');if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');after?.();};setTimeout(finish,reducedMotion.matches?0:180);}
  function closeAllThen(fn){const open=$$('dialog[open]');if(!open.length){fn();return;}let n=open.length;open.forEach(d=>closeDialog(d.id,()=>{n--;if(!n)fn();}));}
  const activeServices = () => SERVICES.filter(s=>!store.disabledServices.includes(s.id));

  function renderRitual(category=activeRitual, changeImage=true){
    if(!CATEGORIES[category])return;activeRitual=category;
    $$('[data-ritual]').forEach(btn=>{const chosen=btn.dataset.ritual===category;btn.setAttribute('aria-selected',String(chosen));btn.tabIndex=chosen?0:-1;});
    const data=CATEGORIES[category], panel=$('#ritual-panel');panel.setAttribute('aria-labelledby','tab-'+category);
    const entries=activeServices().filter(s=>s.category===category).slice(0,3);
    panel.innerHTML=`<p>${esc(data.description)}</p>`+entries.map(s=>{
      const price=s.variants.find(x=>x.price!=null)?.price;
      const meta=s.enquiry?'Details by enquiry':s.demoDuration?'Illustrative duration in booking preview':s.variants.map(x=>x.minutes).join(' / ')+' minutes';
      return `<div class="service-row"><div><strong>${esc(s.short)}</strong><small>${esc(meta)}</small></div><button data-book="${s.id}" aria-label="Preview ${esc(s.name)}">${price!=null?'From '+money(price):'Enquire'} <span aria-hidden="true">&#8599;</span></button></div>`;
    }).join('');
    if(!entries.length)panel.innerHTML+='<div class="empty-state">These services are paused in the studio demo. Re-enable them in the service catalogue.</div>';
    $('#ritual-image-label').textContent=data.label;
    if(changeImage){const img=$('#ritual-image');img.classList.add('changing');setTimeout(()=>{img.src=data.image;img.classList.remove('changing');},reducedMotion.matches?0:170);animateContent(panel);}
  }

  function credits(id){const p=PACKAGES[id];if(!p)return null;const associated=store.appointments.filter(a=>a.packageId===id);const used=p.used+associated.filter(a=>a.status==='completed').length;const held=associated.filter(a=>a.status==='booked').length;return {total:p.total,used,held,remaining:Math.max(0,p.total-used),available:Math.max(0,p.total-used-held)};}
  function bookService(){return serviceById(book.serviceId);}
  function selectedVariant(){const s=bookService();return s.variants.find(v=>v.minutes===book.minutes) || s.variants[0] || {minutes:null,price:null};}
  function bookingPrice(){const p=selectedVariant().price;return p==null?null:p*book.guests;}
  function bookGuest(){return book.packageId?PACKAGES[book.packageId].label:'Preview guest';}
  function openBooking(id='signature',options={}){
    if(id==='default')id=activeServices().find(x=>x.id==='signature')?.id || activeServices()[0]?.id;
    let s=serviceById(id);if(!s || store.disabledServices.includes(id)){toast('That service is paused in this demo. Choose another ritual.');return;}
    closeAllThen(()=>{
      book={serviceId:s.id,minutes:options.packageId?120:(s.variants.find(x=>x.minutes===90)||s.variants[0]||{}).minutes||null,guests:1,therapist:'any',date:today(),slot:null,step:1,ack:false,evening:!!options.evening,packageId:options.packageId||null,recordId:null};
      renderBooking();showDialog('booking-dialog');$('#booking-title')?.focus({preventScroll:true});
    });
  }
  function slotResources(s,minutes,guests,therapist,date,start,excludeId=null){
    if(!minutes || !inBookingRange(date) || start<600 || start+minutes+BUFFER>1440)return null;
    if(date===today() && start<minuteNow()+30)return null;
    const end=start+minutes+BUFFER;
    const conflicts=store.appointments.filter(a=>a.id!==excludeId && a.date===date && a.status!=='cancelled' && start<a.start+a.minutes+BUFFER && end>a.start);
    let capable=s.id==='consultation'?['Specialist C']:STAFF;
    if(therapist!=='any')capable=capable.filter(t=>t===therapist);
    const available=capable.filter(t=>!conflicts.some(a=>a.therapists.includes(t)));
    if(available.length<guests)return null;
    const roomOptions=guests===2?['Together suite']:ROOMS;
    const room=roomOptions.find(r=>!conflicts.some(a=>a.room===r));
    if(!room)return null;
    return {therapists:available.slice(0,guests),room};
  }
  function availableSlots(s,minutes,guests,therapist,date,evening=false,excludeId=null){
    const arr=[];for(let start=evening?1080:600;start+minutes+BUFFER<=1440;start+=30){arr.push({start,resources:slotResources(s,minutes,guests,therapist,date,start,excludeId)});}return arr;
  }
  function renderBooking(focusHeading=false){
    if(!book)return;const s=bookService(), variant=selectedVariant();
    $('#booking-progress').textContent=book.step===4?'PREVIEW COMPLETE':`${String(book.step).padStart(2,'0')} / ${['','YOUR RITUAL','YOUR MOMENT','A FINAL LOOK'][book.step]}`;
    $('#booking-summary').innerHTML=`<div class="booking-summary"><strong>${esc(s.short)}</strong><span>${s.enquiry?'Enquiry preview':`${book.minutes} minutes${s.demoDuration?' (demo)':''} \u00b7 ${book.guests===2?'Two guests':'One guest'}`}</span>${book.step>1&&!s.enquiry?`<span>${esc(prettyDate(book.date))}${book.slot!=null?' \u00b7 '+timeLabel(book.slot):''}</span>`:''}<span class="summary-price">${book.packageId?'1 demo package credit':money(bookingPrice())}</span><span>${book.packageId?esc(PACKAGES[book.packageId].name):'Reference only \u00b7 not a live offer'}</span></div>`;
    const body=$('#booking-body'),footer=$('#booking-footer');
    if(book.step===1){
      body.innerHTML=`<h2 id="booking-title" tabindex="-1">What feels right<br><em>today?</em></h2><p class="intro">Choose a ritual. We'll take care of the little details in this booking demonstration.</p><label class="field-label" for="booking-service">YOUR TREATMENT</label><select class="booking-select" id="booking-service">${activeServices().map(x=>`<option value="${x.id}"${x.id===s.id?' selected':''}>${esc(x.name)}</option>`).join('')}</select><p class="booking-service-desc">${esc(s.description)}</p>${s.enquiry?`<div class="notice-box">This treatment begins with an enquiry. Current pricing and duration are not verified, so this preview will not invent an appointment or a fee.</div>`:`<span class="field-label">${s.demoDuration?'ILLUSTRATIVE APPOINTMENT LENGTH':'MAKE TIME FOR YOURSELF'}</span><div class="segmented" aria-label="Treatment duration">${s.variants.map(x=>`<button data-duration="${x.minutes}" aria-pressed="${x.minutes===book.minutes}">${x.minutes} min<small>${x.price==null?'Fee to confirm':money(x.price)}</small></button>`).join('')}</div><div class="booking-meta-row"><div><label class="field-label" for="booking-guests">YOUR COMPANY</label><select class="booking-select" id="booking-guests"><option value="1"${book.guests===1?' selected':''}>Just me</option>${s.couples?`<option value="2"${book.guests===2?' selected':''}>Two guests</option>`:''}</select></div><div><label class="field-label" for="booking-therapist">SPECIALIST PREFERENCE</label><select class="booking-select" id="booking-therapist"${book.guests===2?' disabled':''}><option value="any">Any specialist</option>${(s.id==='consultation'?['Specialist C']:STAFF).map(t=>`<option value="${t}"${book.therapist===t?' selected':''}>${t}</option>`).join('')}</select></div></div>${s.id==='signature' && book.guests===1?`<label class="review-checkbox" style="margin-top:20px"><input type="checkbox" id="use-credit"${book.packageId?' checked':''}> <span>Try a VIP session credit ${book.packageId?'\u2014 '+esc(PACKAGES[book.packageId].name):'\u2014 Prestige Glow demo'}<br><small>Uses a 120-minute massage. A credit is held, not redeemed, until completed.</small></span></label>`:''}<p class="subtle-note">${s.demoDuration?'Duration is a sample setting, not a published Prestige duration. ':''}${book.guests===2?'Two guests require two demo specialists and the Together suite at the same time. Reference price is per person.':'Staff names, rooms, and availability are synthetic.'}</p>`}`;
      footer.innerHTML=`<div class="booking-total"><small>${book.packageId?'DEMO CREDIT':'REFERENCE TOTAL'+(book.guests===2?' / TWO GUESTS':'')}</small><strong>${book.packageId?'1 session':money(bookingPrice())}</strong></div><button class="solid-button" data-action="book-next">${s.enquiry?'Preview enquiry':'Choose your moment'} <span aria-hidden="true">&#8594;</span></button>`;
    } else if(book.step===2){
      const days=Array.from({length:7},(_,i)=>offsetDate(today(),i));
      const slots=availableSlots(s,book.minutes,book.guests,book.therapist,book.date,book.evening);
      const selectedAvailable=slots.find(x=>x.start===book.slot)?.resources;
      if(book.slot!=null&&!selectedAvailable)book.slot=null;
      body.innerHTML=`<h2 id="booking-title" tabindex="-1">Choose your<br><em>moment.</em></h2><p class="intro">A little space in your day. All times below are simulated and shown in Philippine time (UTC+8).</p><div class="date-strip" aria-label="Choose a date">${days.map((day,i)=>`<button data-date="${day}" aria-pressed="${day===book.date}" aria-label="${esc(prettyDate(day,{weekday:'long',month:'long',day:'numeric'}))}"><small>${i===0?'TODAY':prettyDate(day,{weekday:'short'}).toUpperCase()}</small><strong>${Number(day.slice(-2))}</strong><small>${prettyDate(day,{month:'short'}).toUpperCase()}</small></button>`).join('')}</div><div class="date-toolbar"><span>${esc(prettyDate(book.date,{weekday:'long',month:'short',day:'numeric'}))}</span><label for="booking-date" class="sr-only">Choose another date, up to 60 days ahead</label><input id="booking-date" type="date" value="${book.date}" min="${today()}" max="${offsetDate(today(),60)}" aria-label="Choose another date"></div><div class="segmented" aria-label="Time of day"><button data-evening-filter="all" aria-pressed="${!book.evening}">All moments</button><button data-evening-filter="evening" aria-pressed="${book.evening}">After 6 PM</button></div><div class="time-grid" aria-label="Simulated appointment times">${slots.map(x=>`<button data-slot="${x.start}" aria-pressed="${book.slot===x.start}"${x.resources?'':' disabled'} aria-label="${timeLabel(x.start)}${x.resources?' - demo availability':' - unavailable in demo'}">${timeLabel(x.start)}</button>`).join('')}</div>${slots.some(x=>x.resources)?'':'<div class="empty-state">No demonstration slots match. Try another day, specialist, or time filter.</div>'}<p class="subtle-note">Availability checks demo staff, rooms, treatment length, and a 15-minute reset buffer. This is not connected to Prestige's schedule.</p>`;
      footer.innerHTML=`<button class="back-button" data-action="book-back">&#8592; Your ritual</button><button class="solid-button" data-action="book-next"${book.slot==null?' disabled':''}>Review your moment <span aria-hidden="true">&#8594;</span></button>`;
    } else if(book.step===3){
      const resource=s.enquiry?null:slotResources(s,book.minutes,book.guests,book.therapist,book.date,book.slot);
      body.innerHTML=`<h2 id="booking-title" tabindex="-1">A moment,<br><em>just for you.</em></h2><p class="intro">A final look at your ${s.enquiry?'enquiry':'appointment'} preview. Nothing here is sent to Prestige.</p><dl class="booking-review"><div><dt>Your ritual</dt><dd>${esc(s.name)}</dd></div>${s.enquiry?'':`<div><dt>Your moment</dt><dd>${esc(prettyDate(book.date))}<br>${timeLabel(book.slot)} \u00b7 ${book.minutes} min${s.demoDuration?' (illustrative)':''}</dd></div><div><dt>Guests</dt><dd>${book.guests===2?'Two guests':'One guest'}</dd></div><div><dt>Demo allocation</dt><dd>${resource?esc(resource.therapists.join(' + '))+'<br>'+esc(resource.room):'Slot no longer available'}</dd></div>`}<div><dt>Guest</dt><dd>${esc(bookGuest())}<br><small>No personal information required</small></dd></div><div><dt>${book.packageId?'Package credit':'Reference price'}</dt><dd>${book.packageId?'1 \u00d7 120-minute massage':money(bookingPrice())}<br><small>${book.packageId?'Held now, redeemed only on demo completion':'Current price and terms require confirmation'}</small></dd></div></dl><label class="review-checkbox"><input type="checkbox" id="booking-ack"${book.ack?' checked':''}><span>I understand this is a demonstration, not a real appointment${s.enquiry?' or enquiry submission':''}. No payment will be collected.</span></label><div class="notice-box">${s.id==='consultation'?'This preview is for a consultation only. No procedure, practitioner qualification, outcome, or medical suitability is represented or guaranteed.':'For an actual appointment, contact Prestige directly using the details on the guest site.'}</div>`;
      footer.innerHTML=`<button class="back-button" data-action="book-back">&#8592; ${s.enquiry?'Your ritual':'Your moment'}</button><button class="solid-button" data-action="book-complete"${book.ack?'':' disabled'}>Create ${s.enquiry?'enquiry':'booking'} preview <span aria-hidden="true">&#8594;</span></button>`;
    } else {
      body.innerHTML=`<div class="success-mark" aria-hidden="true">&#10003;</div><p class="eyebrow">${s.enquiry?'ENQUIRY':'BOOKING'} DEMONSTRATION COMPLETE</p><h2 id="booking-title" tabindex="-1">Your moment,<br><em>imagined.</em></h2><p class="intro">${s.enquiry?'Your enquiry preview is complete. It has not been sent or scheduled.':'Your demo booking has been added to this browser\u2019s studio view. It is not an appointment with Prestige.'}</p><div class="notice-box"><strong>No real reservation. No charge. No message sent.</strong><br>${s.enquiry?'Current pricing and treatment details should be confirmed directly with Prestige.':'You can explore rescheduling, cancellation, and reporting in the operations demo.'}</div>${book.recordId?`<p class="success-reference">REFERENCE / ${esc(book.recordId)}</p><div class="completion-links"><button data-action="calendar">Save demo calendar file &#8599;</button><button data-action="view-booking">View in studio &#8599;</button></div>`:''}`;
      footer.innerHTML='<button class="back-button" data-action="new-booking">Explore another ritual</button><button class="solid-button" data-close="booking-dialog">Back to your day &#8599;</button>';
    }
    if(focusHeading){animateContent(body);$('#booking-title')?.focus({preventScroll:true});$('.booking-dialog').scrollTop=0;}
  }
  function completeBooking(){
    if(!book || !book.ack)return;
    const s=bookService();
    if(store.disabledServices.includes(s.id)){toast('This service has been paused. Please choose another ritual.');book.step=1;renderBooking(true);return;}
    if(s.enquiry){book.step=4;renderBooking(true);return;}
    const allocation=slotResources(s,book.minutes,book.guests,book.therapist,book.date,book.slot);
    if(!allocation){toast('That demo time is no longer available. Please choose another.');book.slot=null;book.step=2;renderBooking(true);return;}
    if(book.packageId && credits(book.packageId).available<1){toast('No unheld credits remain in this demo account.');book.packageId=null;book.step=1;renderBooking(true);return;}
    const id='PW-DEMO-'+Date.now().toString(36).toUpperCase();
    store.appointments.push({id,date:book.date,start:book.slot,serviceId:s.id,minutes:book.minutes,price:bookingPrice(),guests:book.guests,therapists:allocation.therapists,room:allocation.room,status:'booked',guest:bookGuest(),guestType:book.packageId?'returning':'new',source:'Website demo',packageId:book.packageId,createdBy:'user'});
    saveStore();book.recordId=id;book.step=4;renderBooking(true);if(location.hash==='#studio')renderStudio();
  }

  function sourceContent(){return `<p class="eyebrow">CONCEPT NOTES / SEPTEMBER 2026</p><h2 id="info-title">A proposal.<br><em>Not a promise.</em></h2><p>This is an independently created website teaser for Prestige Wellness BGC, prepared for client review. It is not an official business website and does not accept real bookings, enquiries, payments, or package purchases.</p><h3>The visual reference</h3><p>The paper, warm browns, fine serif typography, and beauty images reference the Facebook screenshots supplied by the client. Images in this teaser are crops of that supplied artwork, not invented photographs of the spa. High-resolution, rights-cleared original assets should replace screenshot crops before an approved launch.</p><h3>Services and reference prices</h3><p>Massage rates, the listed address, phone number, and 10 AM\u2013midnight hours come from <a href="https://primer.com.ph/beauty-fashion/prestige-wellness/" target="_blank" rel="noopener noreferrer">Philippine Primer's January 6, 2026 feature</a>, accessed September 9, 2026. Those details still need direct business confirmation before launch.</p><p>Waxing prices were transcribed from the supplied October 27, 2024 Facebook artwork. VIP package totals and inclusions were transcribed from the supplied June 29, 2025 artwork. They are historical references, not confirmed current offers. Expired or undated introductory promotions and unverified Google ratings are intentionally not used.</p><p>Direct extraction of the Google share link and Facebook page could not be completed in this environment. This is not presented as a complete Google Business Profile scrape.</p><h3>What the demonstration does</h3><p>Booking checks a synthetic schedule using 3 sample specialists, 3 rooms, opening hours, 15-minute buffers, and simultaneous resources for 2 guests. Waxing and consultation durations are sample scheduling settings, not verified business durations. Consultation-first booking does not authorize or promise any medical treatment.</p><p>Studio appointments and VIP credits use fictional data stored locally in this browser. No guest contact details, card details, or health information are requested. This is not authentication: the studio view is intentionally public demo data. Local demo data resets when a new day begins in Manila, or through the reset action. Optional Google Fonts requests are the only external page assets; outbound contact links open only when clicked.</p><h3>Before production</h3><p>Confirm branding rights, originals, prices, hours, package terms, practitioner credentials, policies, and room/staff rules with Prestige. Replace local demo storage with an authenticated transactional backend, validated server-side availability, payment processing, notifications, audit logs, and a reviewed privacy/consent flow. A noindex directive is included for this proposal; it is not access control.</p>`;}
  function showInfo(html){$('#info-content').innerHTML=html;showDialog('info-dialog');}
  function showSources(){showInfo(sourceContent());}
  function showFullMenu(){
    showInfo(`<p class="eyebrow">THE PRESTIGE REFERENCE MENU</p><h2 id="info-title">Find your<br><em>kind of care.</em></h2><p class="fine-print">Historical reference prices only. Current prices and availability require confirmation.</p><h3>Massage &amp; body</h3><table class="info-table"><thead><tr><th>Treatment</th><th>Minutes</th><th>Reference</th></tr></thead><tbody>${SERVICES.filter(s=>s.category==='restore'&&!s.enquiry).flatMap(s=>s.variants.map(x=>`<tr><td>${esc(s.short)}</td><td>${x.minutes}</td><td>${money(x.price)}</td></tr>`)).join('')}</tbody></table><p class="fine-print">Source: Philippine Primer, January 6, 2026.</p><h3>Waxing</h3><table class="info-table"><thead><tr><th>Area</th><th>Reference</th></tr></thead><tbody>${WAX_MENU.map(x=>`<tr><td>${esc(x[0])}</td><td>${money(x[1])}</td></tr>`).join('')}</tbody></table><p class="fine-print">Source: Prestige's supplied October 27, 2024 artwork. Durations not published in that reference.</p><h3>Skin &amp; advanced aesthetics</h3><p>HydraFacial and skin-care enquiries; consultation-first exploration of the aesthetic services referenced in Prestige's supplied artwork. No unverified procedure price or medical outcome is advertised.</p><button class="solid-button" data-book="signature">Try a booking preview &#8594;</button>`);
  }
  function showPackage(id){const p=PACKAGES[id];if(!p)return;const c=credits(id);showInfo(`<p class="eyebrow">PRESTIGE PRIVILEGES / REFERENCE PROGRAMME</p><h2 id="info-title">${esc(p.name)}</h2><p>${esc(p.description)}</p><h3>${money(p.price)}</h3><p class="fine-print">Published in the supplied June 29, 2025 Facebook artwork. Current availability, eligible massages, validity, transfer rules, refunds, and all terms are unconfirmed.</p><div class="notice-box"><strong>Try the guest-credit experience.</strong><br>A fictional account currently has ${c.available} unheld massage credits. Booking holds one; completing the appointment in Studio redeems it. Cancelling releases a hold.</div><button class="solid-button" data-credit-package="${id}"${c.available<1?' disabled':''}>Preview a credit booking &#8594;</button><p class="fine-print" style="margin-top:18px">No package is purchased, gifted, or activated. This is a browser-only demonstration.</p>`);}

  function inReport(a){return a.date>=offsetDate(today(),-(reportPeriod-1)) && a.date<=today();}
  function reportRecords(){return store.appointments.filter(inReport);}
  const paidValue=a=>a.status==='completed' && !a.packageId ? Number(a.price)||0 : 0;
  function reportMetrics(){const all=reportRecords(),visits=all.filter(a=>a.status!=='cancelled');const revenue=all.reduce((sum,a)=>sum+paidValue(a),0);const used=visits.reduce((sum,a)=>sum+a.minutes*a.guests,0);return {revenue,visits:visits.length,utilization:100*used/(3*14*60*reportPeriod),returning:visits.length?100*visits.filter(a=>a.guestType==='returning').length/visits.length:0};}
  function sortedAppointments(list){return [...list].sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start);}
  function upcomingAppointments(){return sortedAppointments(store.appointments.filter(a=>a.status==='booked'&&(a.date>today() || a.date===today()&&a.start>=minuteNow())));}
  function statusHtml(a){return `<span class="status ${esc(a.status)}">${a.status==='booked'&&a.serviceId==='consultation'?'Consultation':a.status[0].toUpperCase()+a.status.slice(1)}</span>`;}
  function appointmentTable(records,compact=false){if(!records.length)return '<div class="empty-state">No demo appointments match this view.</div>';return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>GUEST / DEMO</th><th>RITUAL</th><th>WHEN / MANILA</th>${compact?'':'<th>REFERENCE VALUE</th>'}<th>STATUS</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${records.map(a=>`<tr><td>${esc(a.guest)}<small>${a.createdBy==='user'?'Created in this prototype':'Synthetic guest record'}</small></td><td>${esc(serviceById(a.serviceId)?.short||a.serviceId)}<small>${a.minutes} min \u00b7 ${a.guests} guest${a.guests===2?'s':''}</small></td><td>${esc(prettyDate(a.date,{month:'short',day:'numeric'}))} \u00b7 ${timeLabel(a.start)}<small>${esc(a.therapists.join(' + '))}</small></td>${compact?'':`<td>${a.packageId?'1 VIP credit':money(a.price)}</td>`}<td>${statusHtml(a)}</td><td><button class="table-action" data-appointment="${esc(a.id)}" aria-label="Manage ${esc(a.guest)} appointment on ${esc(a.date)}">&#8599;</button></td></tr>`).join('')}</tbody></table></div>`;}
  function chartGroups(){
    const all=reportRecords();let groups=[];
    if(reportPeriod===1){for(let h=10;h<24;h+=2){groups.push({label:`${h%12||12}${h>=12?'p':'a'}`,value:all.filter(a=>a.start>=h*60&&a.start<(h+2)*60).reduce((s,a)=>s+paidValue(a),0)});}}
    else if(reportPeriod===7){for(let i=6;i>=0;i--){const date=offsetDate(today(),-i);groups.push({label:prettyDate(date,{weekday:'short'}),value:all.filter(a=>a.date===date).reduce((s,a)=>s+paidValue(a),0)});}}
    else {for(let i=0;i<5;i++){const start=offsetDate(today(),-29+i*6),end=offsetDate(start,5);groups.push({label:prettyDate(start,{month:'short',day:'numeric'}),value:all.filter(a=>a.date>=start&&a.date<=end).reduce((s,a)=>s+paidValue(a),0)});}}
    return groups;
  }
  function renderOverview(){const m=reportMetrics(),groups=chartGroups(),max=Math.max(1,...groups.map(g=>g.value));const categoryNames={restore:'Massage & body',smooth:'Beauty rituals',renew:'Skin & facials',refine:'Consultations'};const breakdown=Object.entries(categoryNames).map(([id,label])=>({label,value:reportRecords().filter(a=>serviceById(a.serviceId)?.category===id).reduce((s,a)=>s+paidValue(a),0)}));
    return `<div class="studio-heading"><div><p class="eyebrow">PRESTIGE / AT A GLANCE</p><h1>A considered overview.</h1><p>${esc(prettyDate(today(),{weekday:'long',month:'long',day:'numeric',year:'numeric'}))} \u00b7 Asia/Manila</p></div><div class="studio-actions"><label class="sr-only" for="report-period">Report period</label><select id="report-period"><option value="1"${reportPeriod===1?' selected':''}>Today</option><option value="7"${reportPeriod===7?' selected':''}>Last 7 days</option><option value="30"${reportPeriod===30?' selected':''}>Last 30 days</option></select><button class="outline-button" data-action="export-report">Export report &#8595;</button></div></div><div class="metric-grid"><div class="metric"><span>Collected revenue / demo</span><strong>${money(m.revenue)}</strong><small>Completed, non-credit visits only</small></div><div class="metric"><span>Visits in selected period</span><strong>${m.visits}</strong><small>Booked + completed; excludes cancelled</small></div><div class="metric"><span>Therapist utilization</span><strong>${Math.round(m.utilization)}<span style="font-size:.6em">%</span></strong><small>3 demo staff \u00d7 14 hours per day</small></div><div class="metric"><span>Returning visits</span><strong>${Math.round(m.returning)}<span style="font-size:.6em">%</span></strong><small>Visit mix; not unique client retention</small></div></div><div class="dashboard-columns"><section class="dashboard-card"><h2>Collected revenue</h2><p>${reportPeriod===1?'Today, in 2-hour blocks':reportPeriod===7?'Last 7 days, by day':'Last 30 days, in 6-day blocks'} \u00b7 synthetic PHP values</p><div class="chart" role="group" aria-label="Demo collected revenue chart">${groups.map(g=>`<div class="chart-col"><button class="chart-bar" style="height:${Math.max(1,g.value/max*100)}%" aria-label="${esc(g.label)}: ${money(g.value)}"><span>${money(g.value)}</span></button><small>${esc(g.label)}</small></div>`).join('')}</div><div class="chart-caption">Total for selected period: ${money(m.revenue)}. No real payments.</div></section><section class="dashboard-card"><h2>Revenue by ritual</h2><p>The same reporting period and revenue definition.</p><div class="service-breakdown">${breakdown.map(g=>`<div class="breakdown-item"><div><span>${g.label}</span><span>${money(g.value)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${m.revenue?g.value/m.revenue*100:0}%"></div></div></div>`).join('')}</div></section></div><section class="dashboard-card wide"><div class="card-heading"><h2>Upcoming moments</h2><button data-studio="appointments">Open appointment book &#8599;</button></div>${appointmentTable(upcomingAppointments().slice(0,5),true)}</section><p class="studio-footnote">All numbers are derived from the included demo records. Reference service values are not actual spa revenue. Package cash sales and medical procedure revenue are not modeled. Capacity, working hours, and staff are illustrative. There is no business-data connection.</p>`;
  }
  function filteredAppointments(){let list=store.appointments;if(appFilter==='upcoming')list=upcomingAppointments();else if(appFilter!=='all')list=list.filter(a=>a.status===appFilter);const q=appQuery.toLowerCase().trim();if(q)list=list.filter(a=>[a.id,a.guest,serviceById(a.serviceId)?.name,a.date,a.therapists.join(' ')].join(' ').toLowerCase().includes(q));return sortedAppointments(list);}
  function renderAppointments(){const list=filteredAppointments();return `<div class="studio-heading"><div><p class="eyebrow">PRESTIGE / THE APPOINTMENT BOOK</p><h1>Every moment, considered.</h1><p>Reschedule, complete, or cancel a synthetic appointment.</p></div><div class="studio-actions"><button class="outline-button" data-action="export-appointments">Export this view &#8595;</button><button class="solid-button" data-book="default">New demo booking +</button></div></div><div class="studio-filter"><label class="sr-only" for="appointment-search">Search appointments by guest, treatment, date, or reference</label><input type="search" id="appointment-search" value="${esc(appQuery)}" placeholder="Search guest, ritual, or reference"><div class="filter-tabs" aria-label="Appointment filters">${[['upcoming','Upcoming'],['all','All'],['completed','Completed'],['cancelled','Cancelled']].map(([id,label])=>`<button data-app-filter="${id}" class="${appFilter===id?'active':''}" aria-pressed="${appFilter===id}">${label}</button>`).join('')}</div></div><section class="dashboard-card"><div class="card-heading"><h2 id="appointment-count">${list.length} demonstration appointment${list.length===1?'':'s'}</h2></div><div id="appointment-results">${appointmentTable(list)}</div></section><p class="studio-footnote">These are fictional appointments, not reception records. All times are in Philippine time (UTC+8). Status changes have no external effect. Demo cancellation fees are not modeled; Prestige's actual policies remain unconfirmed.</p>`;}
  function updateAppointmentSearch(){const list=filteredAppointments();$('#appointment-results').innerHTML=appointmentTable(list);$('#appointment-count').textContent=`${list.length} demonstration appointment${list.length===1?'':'s'}`;}
  function renderPackages(){return `<div class="studio-heading"><div><p class="eyebrow">PRESTIGE / GUEST PRIVILEGES</p><h1>Care that carries forward.</h1><p>Illustrative accounts. Credits are held on booking and redeemed on completion.</p></div></div><div class="credit-grid">${Object.values(PACKAGES).map(p=>{const c=credits(p.id);return `<article class="credit-card"><span class="eyebrow">${esc(p.label.toUpperCase())}</span><h2>${esc(p.name)}</h2><p>Synthetic account \u00b7 not a customer record</p><div class="credit-count">${c.remaining} <span>/ ${p.total}</span></div><div class="progress-track"><div class="progress-fill" style="width:${c.remaining/p.total*100}%"></div></div><small>Massage sessions remaining</small><p style="margin-top:15px">${c.available} available \u00b7 ${c.held} held \u00b7 ${c.used} redeemed</p>${p.extra?`<p>${p.extra-p.extraUsed} / ${p.extra} ${esc(p.extraName)} remaining<br><small>Illustrative balance; extra-treatment redemption not implemented.</small></p>`:''}<button data-credit-package="${p.id}"${c.available<1?' disabled':''}>Preview a credit reservation &#8599;</button></article>`;}).join('')}</div><div class="notice-box" style="margin-top:28px">Package expiry, transferability, eligible massage types, cancellation rules, accounting allocation, and sale terms require client confirmation. No expiration date, savings calculation, or monetary liability is invented here.</div><p class="studio-footnote">Existing redeemed balances are synthetic starting values. New demo bookings place a hold; completion redeems a session; cancellation releases the hold. Revenue cards exclude credit redemptions to avoid pretending they are new cash receipts.</p>`;}
  function renderCatalogue(){return `<div class="studio-heading"><div><p class="eyebrow">PRESTIGE / SERVICE CATALOGUE</p><h1>A menu that can evolve.</h1><p>Pause a service to remove it from this browser's guest booking choices.</p></div><button class="outline-button" data-action="sources">Reference &amp; scope notes &#8599;</button></div><section class="dashboard-card">${SERVICES.map(s=>{const enabled=!store.disabledServices.includes(s.id);return `<div class="catalogue-row"><div><h3>${esc(s.name)}</h3><p>${s.enquiry?'Enquiry only \u00b7 pricing unconfirmed':s.variants.map(v=>`${v.minutes} min / ${money(v.price)}`).join(' \u00b7 ')}${s.demoDuration?' \u00b7 demo duration':''}</p><p>${esc(s.source)}</p></div><button data-toggle-service="${s.id}" aria-pressed="${enabled}" aria-label="${enabled?'Pause':'Enable'} ${esc(s.name)}">${enabled?'Enabled':'Paused'}</button></div>`;}).join('')}</section><p class="studio-footnote">These toggles update the guest site immediately in this browser only. They are not a secured content-management system. Pricing edits, staff configuration, role permissions, audit history, and multi-user synchronization belong in the production phase.</p><button class="outline-button" data-action="reset-demo" style="margin-top:25px">Restore all demo defaults</button>`;}
  function renderStudio(tab=studioTab){studioTab=tab;$$('[data-studio]', $('#studio-view')).forEach(b=>{b.classList.toggle('active',b.dataset.studio===tab);if(b.closest('nav'))b.setAttribute('aria-current',b.dataset.studio===tab?'page':'false');});$('#studio-content').innerHTML=({overview:renderOverview,appointments:renderAppointments,packages:renderPackages,catalogue:renderCatalogue}[tab]||renderOverview)();}
  function route(){const studio=location.hash==='#studio';$('#site-view').hidden=studio;$('#studio-view').hidden=!studio;if(studio){renderStudio();document.title='Prestige Studio \u2014 Operations Demo';window.scrollTo({top:0,behavior:'instant'});}else{document.title='Prestige Wellness BGC \u2014 A little more you.';requestAnimationFrame(()=>{$$('.reveal').forEach(el=>observer?.observe(el));if(location.hash&&document.getElementById(location.hash.slice(1)))document.getElementById(location.hash.slice(1)).scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'});});}}
  function appointmentDetails(id){const a=store.appointments.find(x=>x.id===id);if(!a)return;const s=serviceById(a.serviceId);showInfo(`<p class="eyebrow">STUDIO / DEMO APPOINTMENT</p><h2 id="info-title">${esc(s.short)}</h2><p>${esc(a.guest)} \u00b7 ${statusHtml(a)}</p><dl class="booking-review"><div><dt>Reference</dt><dd>${esc(a.id)}</dd></div><div><dt>When</dt><dd>${esc(prettyDate(a.date))}<br>${timeLabel(a.start)} \u00b7 ${a.minutes} minutes</dd></div><div><dt>Allocation</dt><dd>${esc(a.therapists.join(' + '))}<br>${esc(a.room)}</dd></div><div><dt>Reference value</dt><dd>${a.packageId?'1 credit \u2014 '+esc(PACKAGES[a.packageId].name):money(a.price)}</dd></div></dl><p class="fine-print">This is a fictional record. No notifications or payment actions will occur.</p>${a.status==='booked'?`<div class="studio-actions" style="flex-wrap:wrap"><button class="solid-button" data-reschedule="${esc(id)}">Reschedule &#8594;</button><button class="outline-button" data-complete-appointment="${esc(id)}">Mark completed</button><button class="outline-button" data-request-cancel="${esc(id)}">Cancel demo visit</button></div>`:''}<div id="appointment-confirmation"></div>`);}
  function updateAppointment(id,status){const a=store.appointments.find(x=>x.id===id);if(!a || a.status!=='booked')return;a.status=status;saveStore();closeDialog('info-dialog');renderStudio();toast(status==='cancelled'?'Demo appointment cancelled. Any package hold has been released.':'Demo appointment completed. Reporting and credits updated.');}
  function renderReschedule(id,date=null){const a=store.appointments.find(x=>x.id===id);if(!a || a.status!=='booked')return;const day=date||((a.date>=today())?a.date:today());pendingReschedule={id,date:day,start:null};const s=serviceById(a.serviceId);const slots=availableSlots(s,a.minutes,a.guests,'any',day,false,id);showInfo(`<p class="eyebrow">STUDIO / RESCHEDULE PREVIEW</p><h2 id="info-title">A different<br><em>moment.</em></h2><p>${esc(a.guest)} \u00b7 ${esc(s.short)} \u00b7 ${a.minutes} minutes</p><label class="field-label" for="reschedule-date">CHOOSE A DATE / MANILA</label><input class="booking-select" type="date" id="reschedule-date" value="${day}" min="${today()}" max="${offsetDate(today(),60)}"><div class="time-grid" style="margin-top:22px;max-height:230px">${slots.map(x=>`<button data-reschedule-slot="${x.start}" aria-pressed="false"${x.resources?'':' disabled'}>${timeLabel(x.start)}</button>`).join('')}</div><p class="fine-print" style="margin-top:16px">Demo availability re-checks all resources and buffers. The original appointment is excluded from the conflict check. No real booking is changed.</p><div class="studio-actions" style="margin-top:20px"><button class="back-button" data-appointment="${esc(id)}">&#8592; Back</button><button class="solid-button" data-action="save-reschedule" disabled>Save demo change &#8594;</button></div>`);}
  function saveReschedule(){if(!pendingReschedule || pendingReschedule.start==null)return;const a=store.appointments.find(x=>x.id===pendingReschedule.id);if(!a)return;const resource=slotResources(serviceById(a.serviceId),a.minutes,a.guests,'any',pendingReschedule.date,pendingReschedule.start,a.id);if(!resource){toast('That demonstration time is no longer available.');renderReschedule(a.id,pendingReschedule.date);return;}Object.assign(a,{date:pendingReschedule.date,start:pendingReschedule.start,...resource});saveStore();pendingReschedule=null;closeDialog('info-dialog');renderStudio();toast('Demo appointment rescheduled. No message was sent.');}
  function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function csvCell(value){let s=String(value??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
  function exportRecords(records,name){const headers=['Demo reference','Date (Asia/Manila)','Start','Guest (synthetic)','Treatment','Minutes','Guests','Demo specialists','Demo room','Status','Reference PHP value','Demo collected PHP','Package credit','Demo booking source'];const rows=records.map(a=>[a.id,a.date,timeLabel(a.start),a.guest,serviceById(a.serviceId)?.name,a.minutes,a.guests,a.therapists.join(' + '),a.room,a.status,a.price??'',paidValue(a),a.packageId||'',a.source]);download(`${name}-${today()}.csv`,'\uFEFF'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Demo export prepared. No real customer data is included.');}
  function exportCalendar(){const a=store.appointments.find(x=>x.id===book?.recordId);if(!a)return;const start=new Date(a.date+'T'+String(Math.floor(a.start/60)).padStart(2,'0')+':'+String(a.start%60).padStart(2,'0')+':00+08:00');const dt=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const end=new Date(start.getTime()+a.minutes*60000);const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Prestige Concept//DEMO ONLY//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+a.id+'@prestige-demo.invalid','DTSTAMP:'+dt(new Date()),'DTSTART:'+dt(start),'DTEND:'+dt(end),'SUMMARY:DEMO ONLY - '+serviceById(a.serviceId).short,'DESCRIPTION:Not a real appointment. No reservation or payment exists. This calendar event is an illustration only.','STATUS:TENTATIVE','TRANSP:TRANSPARENT','END:VEVENT','END:VCALENDAR'].join('\r\n');download('prestige-DEMO-NOT-A-BOOKING.ics',content,'text/calendar;charset=utf-8');}

  /* Delegated actions allow every dynamically rendered view to stay interactive. */
  document.addEventListener('click',event=>{
    const target=event.target.closest('button,a');if(!target)return;
    if(target.dataset.close){event.preventDefault();closeDialog(target.dataset.close);return;}
    if(target.dataset.book){event.preventDefault();openBooking(target.dataset.book,{evening:target.dataset.evening==='true'});return;}
    if(target.dataset.category){renderRitual(target.dataset.category);return;}
    if(target.dataset.ritual){renderRitual(target.dataset.ritual);return;}
    if(target.dataset.package){showPackage(target.dataset.package);return;}
    if(target.dataset.creditPackage){openBooking('signature',{packageId:target.dataset.creditPackage});return;}
    if(target.dataset.studio){event.preventDefault();studioTab=target.dataset.studio;if(location.hash!=='#studio')location.hash='studio';else{renderStudio();window.scrollTo({top:0,behavior:'instant'});}return;}
    if(target.dataset.duration && book){book.minutes=Number(target.dataset.duration);book.slot=null;if(book.minutes!==120)book.packageId=null;renderBooking();$(`[data-duration="${book.minutes}"]`)?.focus({preventScroll:true});return;}
    if(target.dataset.date && book){book.date=target.dataset.date;book.slot=null;book.ack=false;renderBooking();$(`[data-date="${book.date}"]`)?.focus({preventScroll:true});return;}
    if(target.dataset.eveningFilter && book){book.evening=target.dataset.eveningFilter==='evening';book.slot=null;renderBooking();$(`[data-evening-filter="${target.dataset.eveningFilter}"]`)?.focus({preventScroll:true});return;}
    if(target.dataset.slot && book){book.slot=Number(target.dataset.slot);$$('[data-slot]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.slot)===book.slot)));$('[data-action="book-next"]').disabled=false;renderBookingSummaryOnly();return;}
    if(target.dataset.appFilter){appFilter=target.dataset.appFilter;renderStudio();$(`[data-app-filter="${appFilter}"]`)?.focus({preventScroll:true});return;}
    if(target.dataset.appointment){appointmentDetails(target.dataset.appointment);return;}
    if(target.dataset.reschedule){renderReschedule(target.dataset.reschedule);return;}
    if(target.dataset.rescheduleSlot){pendingReschedule.start=Number(target.dataset.rescheduleSlot);$$('[data-reschedule-slot]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.rescheduleSlot)===pendingReschedule.start)));$('[data-action="save-reschedule"]').disabled=false;return;}
    if(target.dataset.completeAppointment){updateAppointment(target.dataset.completeAppointment,'completed');return;}
    if(target.dataset.requestCancel){$('#appointment-confirmation').innerHTML=`<div class="notice-box">Cancel this fictional appointment and release any credit hold?<br><button class="outline-button" style="margin-top:10px" data-cancel-appointment="${esc(target.dataset.requestCancel)}">Yes, cancel the demo visit</button></div>`;return;}
    if(target.dataset.cancelAppointment){updateAppointment(target.dataset.cancelAppointment,'cancelled');return;}
    if(target.dataset.toggleService){const id=target.dataset.toggleService;store.disabledServices=store.disabledServices.includes(id)?store.disabledServices.filter(x=>x!==id):[...store.disabledServices,id];saveStore();renderRitual(activeRitual,false);renderStudio();$(`[data-toggle-service="${id}"]`)?.focus({preventScroll:true});toast('Demo service catalogue updated in this browser.');return;}
    const action=target.dataset.action;if(!action)return;
    if(action==='sources')showSources();
    else if(action==='full-menu')showFullMenu();
    else if(action==='book-next' && book){if(book.step===1 && book.packageId && credits(book.packageId).available<1){toast('No unheld credits remain. Turn off the demo credit option.');return;}book.step=book.step===1&&bookService().enquiry?3:Math.min(3,book.step+1);renderBooking(true);}
    else if(action==='book-back' && book){book.step=bookService().enquiry?1:Math.max(1,book.step-1);renderBooking(true);}
    else if(action==='book-complete')completeBooking();
    else if(action==='new-booking'){book.step=1;book.recordId=null;book.ack=false;book.slot=null;renderBooking(true);}
    else if(action==='calendar')exportCalendar();
    else if(action==='view-booking'){studioTab='appointments';appFilter='upcoming';appQuery=book.recordId;closeDialog('booking-dialog',()=>{if(location.hash==='#studio')renderStudio();else location.hash='studio';});}
    else if(action==='save-reschedule')saveReschedule();
    else if(action==='export-report')exportRecords(sortedAppointments(reportRecords()),'prestige-demo-report-'+reportPeriod+'-days');
    else if(action==='export-appointments')exportRecords(filteredAppointments(),'prestige-demo-appointments');
    else if(action==='reset-demo')showInfo('<p class="eyebrow">STUDIO / RESET</p><h2 id="info-title">A fresh start.</h2><p>Restore the original fictional appointments, package balances, and enabled services. This only removes demo changes in this browser.</p><button class="solid-button" data-action="confirm-reset">Reset demonstration data &#8594;</button>');
    else if(action==='confirm-reset'){store=seedStore();saveStore();appQuery='';appFilter='upcoming';renderRitual(activeRitual,false);renderStudio();closeDialog('info-dialog');toast('Demo data restored.');}
  });
  function renderBookingSummaryOnly(){const s=bookService();$('#booking-summary').innerHTML=`<div class="booking-summary"><strong>${esc(s.short)}</strong><span>${book.minutes} minutes \u00b7 ${book.guests} guest${book.guests===2?'s':''}</span><span>${esc(prettyDate(book.date))} \u00b7 ${timeLabel(book.slot)}</span><span class="summary-price">${book.packageId?'1 demo package credit':money(bookingPrice())}</span><span>Demonstration only</span></div>`;}
  document.addEventListener('change',event=>{
    const el=event.target;
    if(el.id==='booking-service' && book){const s=serviceById(el.value);book.serviceId=s.id;book.minutes=(s.variants.find(x=>x.minutes===90)||s.variants[0]||{}).minutes||null;book.guests=1;book.therapist='any';book.slot=null;book.packageId=null;renderBooking();$('#booking-service').focus({preventScroll:true});}
    else if(el.id==='booking-guests'&&book){book.guests=Number(el.value);book.slot=null;if(book.guests===2){book.therapist='any';book.packageId=null;}renderBooking();$('#booking-guests').focus({preventScroll:true});}
    else if(el.id==='booking-therapist'&&book){book.therapist=el.value;book.slot=null;}
    else if(el.id==='use-credit'&&book){book.packageId=el.checked?(book.packageId||'glow'):null;if(el.checked){book.minutes=120;book.guests=1;}book.slot=null;renderBooking();$('#use-credit')?.focus({preventScroll:true});}
    else if(el.id==='booking-date'&&book){if(inBookingRange(el.value)){book.date=el.value;book.slot=null;renderBooking();$('#booking-date').focus({preventScroll:true});}else{toast('Choose a date from today to 60 days ahead.');el.value=book.date;}}
    else if(el.id==='booking-ack'&&book){book.ack=el.checked;$('[data-action="book-complete"]').disabled=!book.ack;}
    else if(el.id==='report-period'){reportPeriod=Number(el.value);renderStudio();$('#report-period').focus({preventScroll:true});}
    else if(el.id==='reschedule-date'&&pendingReschedule){if(inBookingRange(el.value)){renderReschedule(pendingReschedule.id,el.value);$('#reschedule-date').focus({preventScroll:true});}else{toast('Choose a date within the next 60 days.');el.value=pendingReschedule.date;}}
  });
  document.addEventListener('input',event=>{if(event.target.id==='appointment-search'){appQuery=event.target.value;updateAppointmentSearch();}});
  $('.ritual-tabs').addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp','ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const tabs=$$('[data-ritual]'),index=tabs.findIndex(t=>t.dataset.ritual===activeRitual);let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(['ArrowDown','ArrowRight'].includes(event.key)?1:-1)+tabs.length)%tabs.length;renderRitual(tabs[next].dataset.ritual);tabs[next].focus();});
  $('#menu-open').addEventListener('click',()=>showDialog('mobile-menu'));
  $$('#mobile-menu nav a').forEach(a=>a.addEventListener('click',()=>closeDialog('mobile-menu')));
  $$('dialog').forEach(dialog=>{
    dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog(dialog.id);});
    dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeDialog(dialog.id);});
    dialog.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');});
  });
  document.addEventListener('keydown',event=>{
    if(event.key!=='Tab')return;
    const dialog=$$('dialog[open]').at(-1);if(!dialog)return;
    const controls=$$('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])',dialog).filter(el=>el.getClientRects().length && el.tabIndex>=0);
    if(!controls.length){event.preventDefault();dialog.focus();return;}
    const first=controls[0],last=controls.at(-1),active=document.activeElement;
    if(event.shiftKey && (active===first || !dialog.contains(active))){event.preventDefault();last.focus();}
    else if(!event.shiftKey && active===last){event.preventDefault();first.focus();}
  });
  window.addEventListener('hashchange',route);
  window.addEventListener('scroll',()=>$('#site-header').classList.toggle('is-scrolled',window.scrollY>45),{passive:true});
  window.addEventListener('storage',event=>{if(event.key===STORE_KEY){store=loadStore();renderRitual(activeRitual,false);if(location.hash==='#studio')renderStudio();}});
  let observer=null;
  store=loadStore();saveStore();renderRitual('restore',false);
  if('IntersectionObserver' in window){document.body.classList.add('js-enabled');observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.06});$$('.reveal').forEach(el=>observer.observe(el));}
  requestAnimationFrame(()=>document.body.classList.add('ready'));
  route();
  // Useful for deterministic, non-production automated QA. No secrets are exposed.
  window.PrestigeDemo={getState:()=>JSON.parse(JSON.stringify(store)),getDate:today,getMetrics:reportMetrics,getCredits:credits,getService:serviceById,getSlots:availableSlots};
})();
